<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';
require_permission('vendors.manage');
$pdo=db();
if(is_post()){
 verify_csrf();
 try{
  $name=trim((string)input('shop_name'));$owner=trim((string)input('owner_name'));$email=filter_var(input('email'),FILTER_VALIDATE_EMAIL)?:null;$mobile=trim((string)input('mobile'));$lat=(float)input('latitude');$lon=(float)input('longitude');$commission=(float)input('commission_rate');$escrow=(float)input('escrow_balance');
  if($name===''||$owner===''||$mobile===''||$lat<-90||$lat>90||$lon<-180||$lon>180||$commission<0||$commission>100||$escrow<0)throw new InvalidArgumentException('Enter valid outlet, owner, coordinates and commercial values.');
  $code='VND_'.strtoupper(bin2hex(random_bytes(5)));$token='vendor://id='.$code.'&commission='.number_format($commission,2,'.','');$pdo->beginTransaction();
  $kyc=(trim((string)input('identity_proof_path'))!==''&&trim((string)input('address_proof_path'))!=='')?'PENDING':'PENDING';
  $pdo->prepare('INSERT INTO vendors(vendor_code,name,shop_name,business_category,owner_name,email,mobile,address,owner_address,logo_path,cover_image_path,latitude,longitude,proximity_radius_m,gstin,identity_proof_path,address_proof_path,bank_account_holder,bank_account_number,bank_ifsc,bank_branch,settlement_upi,commission_rate,escrow_balance,settlement_cycle,kyc_status,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$code,$owner,$name,trim((string)input('category'))?:null,$owner,$email,$mobile,trim((string)input('address')),trim((string)input('owner_address')),trim((string)input('logo_path'))?:null,trim((string)input('cover_image_path'))?:null,$lat,$lon,(int)input('proximity_radius_m',300),trim((string)input('gstin'))?:null,trim((string)input('identity_proof_path'))?:null,trim((string)input('address_proof_path'))?:null,trim((string)input('bank_account_holder'))?:null,trim((string)input('bank_account_number'))?:null,strtoupper(trim((string)input('bank_ifsc')))?:null,trim((string)input('bank_branch'))?:null,trim((string)input('settlement_upi'))?:null,$commission,$escrow,strtoupper((string)input('settlement_cycle','DAILY')),$kyc,'INACTIVE',admin()['id']]);
  audit_log((int)admin()['id'],'VENDOR_ONBOARDED','vendors',$code);$pdo->commit();flash('success','Vendor created as INACTIVE pending KYC and bank verification. QR payload: '.$token);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('/admin/vendors/onboarding.php');
}
$categories=$pdo->query('SELECT id,name,platform_commission_rate,customer_reward_rate FROM video_categories WHERE status="ACTIVE" ORDER BY name')->fetchAll();$pageTitle='Master vendor onboarding';$pageSubtitle='Outlet identity, owner KYC, settlement banking and vendor QR';require APP_ROOT.'/includes/header.php';
?><section class="vendor-onboarding"><div class="vendor-hero"><h2>HUNTER WALLET ADMIN · MASTER VENDOR ONBOARDING &amp; KYC REGISTRATION</h2><span>Single-page outlet, KYC, banking, commission &amp; QR setup</span></div><form method="post" class="form-grid vendor-form"><?=csrf_field()?><h3 class="form-section-title">1. SHOP / OUTLET IDENTITY, LOGO &amp; GPS LOCATION</h3><div class="field"><label>Shop / outlet business name</label><input name="shop_name" required></div><div class="field"><label>Store logo / banner path</label><input name="logo_path" placeholder="/uploads/vendors/logo.png"><input name="cover_image_path" placeholder="/uploads/vendors/banner.png"></div><div class="field"><label>GPS latitude</label><input name="latitude" type="number" step="0.0000001" required></div><div class="field"><label>GPS longitude</label><input name="longitude" type="number" step="0.0000001" required></div><div class="field full"><label>Complete physical address &amp; landmark</label><textarea name="address" required></textarea></div><div class="field"><label>Proximity beacon / radar radius (m)</label><input name="proximity_radius_m" type="number" min="1" value="300"></div><h3 class="form-section-title">2. SHOPKEEPER / OWNER PERSONAL DETAILS &amp; KYC PROOFS</h3><div class="field"><label>Owner full name</label><input name="owner_name" required></div><div class="field"><label>Registered mobile number / login OTP</label><input name="mobile" required></div><div class="field"><label>Official email address</label><input name="email" type="email"></div><div class="field full"><label>Owner personal address</label><textarea name="owner_address"></textarea></div><div class="field"><label>Identity proof path</label><input name="identity_proof_path" placeholder="/uploads/kyc/id-proof.pdf"></div><div class="field"><label>Address proof path</label><input name="address_proof_path" placeholder="/uploads/kyc/address-proof.pdf"></div><div class="field"><label>GSTIN / trade licence</label><input name="gstin"></div><h3 class="form-section-title">3. SETTLEMENT BANK ACCOUNT &amp; PAYOUT CREDENTIALS</h3><div class="field"><label>Bank account holder</label><input name="bank_account_holder"></div><div class="field"><label>Bank account number</label><input name="bank_account_number"></div><div class="field"><label>Bank IFSC &amp; branch</label><input name="bank_ifsc"><input name="bank_branch" placeholder="Branch"></div><div class="field"><label>Settlement UPI / QR ID</label><input name="settlement_upi"></div><div class="field"><label>Automated settlement cycle</label><select name="settlement_cycle"><option>DAILY</option><option>WEEKLY</option><option>MONTHLY</option></select></div><h3 class="form-section-title">4. BUSINESS CATEGORY, COMMISSION RULES &amp; MASTER VENDOR QR</h3><div class="field"><label>Business category</label><input name="category" placeholder="Food & Beverage / Retail"></div><div class="field"><label>Platform commission rate (%)</label><input name="commission_rate" type="number" min="0" max="100" step="0.01" value="5"></div><div class="field"><label>Vendor pre-funded marketing pool (escrow)</label><input name="escrow_balance" type="number" min="0" step="0.01" value="0"></div><div class="field full"><button class="btn">Save vendor &amp; generate QR payload</button></div></form></section><?php require APP_ROOT.'/includes/footer.php';
